alter table SB_DWH.FCT_STMT_ENTRY
  add constraint FCT_STMT_ENTRY_PK primary key (ENTRY_ID)
  using index 
  tablespace SB_DWH_TBS
  pctfree 10
  initrans 2
  maxtrans 255
  storage
  (
    initial 64K
    next 1M
    minextents 1
    maxextents unlimited
  );
